const { useState, useEffect } = React;

function CourseList() {
  const [courses, setCourses] = useState(null);

  useEffect(() => {
    fetch('/api/courses')
      .then((res) => res.json())
      .then((list) => setCourses(list));
  }, []);

  if (courses === null) {
    return <p className="state">불러오는 중…</p>;
  }

  return (
    <div>
      <p className="state">코스 {courses.length}개</p>
      {courses.map((c) => <p className="course" key={c.id}>{c.name}</p>)}
    </div>
  );
}

ReactDOM.createRoot(document.querySelector('#root')).render(<CourseList />);

